const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/async_operations',
  qs: {
    parent_id: 'SOME_STRING_VALUE',
    'filters[operation_type]': 'SOME_STRING_VALUE',
    'filters[started_after]': 'SOME_STRING_VALUE',
    'filters[started_before]': 'SOME_STRING_VALUE',
    'filters[status]': 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/async_operations?parent_id=SOME_STRING_VALUE&filters%5Boperation_type%5D=SOME_STRING_VALUE&filters%5Bstarted_after%5D=SOME_STRING_VALUE&filters%5Bstarted_before%5D=SOME_STRING_VALUE&filters%5Bstatus%5D=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

